sys_script_include.script:
var AITriageEngine = Class.create();
AITriageEngine.prototype = {
    initialize: function() {},

    // 1. Calculate Priority based on Keywords
    evaluatePriority: function(shortDesc) {
        if (!shortDesc) return 3; // Default to moderate if no description
        var text = shortDesc.toLowerCase();
        if (text.indexOf("outage") > -1 || text.indexOf("server down") > -1 || text.indexOf("database crash") > -1) {
            return 1; // Critical P1
        } else if (text.indexOf("hardware") > -1 || text.indexOf("laptop") > -1 || text.indexOf("vpn") > -1) {
            return 2; // High P2
        }
        return 3; // Moderate P3
    },

    // 2. Mock Agentic AI Logic (Generates automated workaround based on issue)
    generateFixPlan: function(shortDesc) {
        if (!shortDesc) return "No description provided for triage.";
        var text = shortDesc.toLowerCase();
        var plan = "[AI] Agentic Triage Plan:\n";

        if (text.indexOf("vpn") > -1) {
            plan += "- Root Cause: Gateway connection timeout.\n- Action Step 1: Clear local DNS cache.\n- Action Step 2: Restart Cisco AnyConnect Service.\n- Action Step 3: Re-authenticate via SSO portal.";
        } else if (text.indexOf("laptop") > -1 || text.indexOf("hardware") > -1) {
            plan += "- Root Cause: Hardware failure/peripheral disconnect.\n- Action Step 1: Query CMDB asset registry.\n- Action Step 2: Auto-route ticket to Hardware Support Group.\n- Action Step 3: Trigger IT inventory dispatch request.";
        } else {
            plan += "- Root Cause: Standard L1 software query.\n- Action Step 1: Search Knowledge Base for KB001092.\n- Action Step 2: Send diagnostic survey link to caller.";
        }

        return plan;
    },

    type: 'AITriageEngine'
};
